import urllib.request
import re
import sys

# The 64 Thiruvilaiyadal Leelas in authentic Tamil canonical tradition
madurai_64_leelas = [
    # 1-18: மதுரைக் காண்டம் (18 லீலைகள்)
    ("இந்திரன் பழி தீர்த்த படலம்", "கடம்பவனத்தில் சுயம்பு லிங்கத்தைக் கண்டு இந்திரன் தன் பிரம்மஹத்தி தோஷம் நீங்கப் பொற்றாமரை மலர்களால் பூஜித்த லீலை."),
    ("வெள்ளை யானையின் சாபம் தீர்த்த படலம்", "துர்வாச முனிவரின் சாபத்தால் காட்டு யானையான ஐராவதம், மதுரையில் ஈசனைப் பூஜித்து சாபவிமோசனம் பெற்று மீண்டும் இந்திரனின் வாகனமான லீலை."),
    ("திருநகரம் கண்ட படலம்", "தனஞ்சயன் என்ற வணிகன் காட்டில் கண்ட ஒளியை குலசேகர பாண்டியனிடம் கூற, ஈசனின் திருவருளால் மதுரை மாநகரம் நிர்மாணிக்கப்பட்ட வரலாறு."),
    ("தடாதகைப் பிராட்டியார் திருவவதாரப் படலம்", "மலையத்துவச பாண்டியனின் புத்திரகாமேஷ்டி வேள்வித் தீயில் மூன்று தனங்களுடன் தடாதகைப் பிராட்டியார் அவதரித்து திக்விஜயம் செய்த லீலை."),
    ("தடாதகைப் பிராட்டியார் திருமணப் படலம்", "கைலாயத்தில் சுந்தரேஸ்வரரைக் கண்டதும் மூன்றாவது தனம் மறைய, மதுரையில் மீனாட்சி-சுந்தரேஸ்வரர் திருக்கல்யாணம் கோலாகலமாக நடைபெற்ற லீலை."),
    ("வெள்ளி அம்பலத் திருக்கூத்தாடிய படலம்", "பதஞ்சலி, வியாக்ரபாத முனிவர்களின் வேண்டுகோளுக்காக நடராஜப் பெருமான் தன் வலது காலைத் தூக்கி வெள்ளி அம்பலத்தில் திருநடனம் ஆடிய லீலை."),
    ("குண்டோதரனுக்கு அன்னமிட்ட படலம்", "திருமண விருந்தில் குண்டோதரனின் அடங்காத பெரும்பசியைத் தீர்க்க மதுரை நகரத்து அன்னக் குவியல்கள் அனைத்தையும் உண்ணச் செய்த லீலை."),
    ("அன்னக்குழியும் வைகையும் அழைத்த படலம்", "குண்டோதரனின் தாகத்தைத் தீர்க்க தன் சடாமுடிக் கங்கையை வைகை நதியாகத் தரையில் ஓடச் செய்து அருள் புரிந்த லீலை."),
    ("ஏழு கடல் அழைத்த படலம்", "ராணி காஞ்சனமாலையின் தீர்த்த யாத்திரை ஆசையை நிறைவேற்ற மதுரையின் நடுவே சப்த சாகரங்களையும் வரவழைத்த லீலை."),
    ("மலையத்துவசனை அழைத்த படலம்", "காஞ்சனமாலையின் ஏக்கம் தீர, சுவர்க்கத்தில் இருந்த மலையத்துவச பாண்டியனை நேரில் வரவழைத்து முக்தி அளித்த லீலை."),
    ("உக்கிர பாண்டியன் திருவவதாரப் படலம்", "அன்னை மீனாட்சிக்கும் சுந்தரேஸ்வரருக்கும் தவப் புதல்வனாக முருகப் பெருமானே உக்கிரகுமார பாண்டியனாக அவதரித்த லீலை."),
    ("உக்கிர பாண்டியனுக்கு வேல், வளை, செண்டு அளித்த படலம்", "சூரிய, இந்திர, மேரு மலைகளை அடக்க உக்கிரகுமாரனுக்கு ஈசன் வெற்றி வேலையும், வளையையும், செண்டையும் அளித்த லீலை."),
    ("கடல் சுவற வேல் விட்ட படலம்", "மதுரையை அழிக்கப் பொங்கி வந்த பெருங்கடலை உக்கிர பாண்டியன் தன் வேல் எறிந்து வற்றச் செய்த லீலை."),
    ("இந்திரன் முடிமேல் வளை எறிந்த படலம்", "மழை தராமல் மறுத்த இந்திரனுடன் போரிட்டு, அவனது வைர முடியைத் தன் கைவளையால் உடைத்தெறிந்த லீலை."),
    ("மேருவைச் செண்டால் அடித்த படலம்", "பஞ்ச காலத்தில் பொன் தராமல் மறுத்த மேரு மலையை உக்கிர பாண்டியன் தன் செண்டால் அடித்துப் பொன்னும் ரத்தினமும் பெற்ற லீலை."),
    ("வேதத்துக்குப் பொருள் அருளிச் செய்த படலம்", "பிரம்மாண்டமான நான்கு வேதங்களின் உண்மைப் பொருளை முனிவர்களுக்கு தட்சிணாமூர்த்தியாக அமர்ந்து உபதேசித்த லீலை."),
    ("மாணிக்கம் விற்ற படலம்", "பாண்டியனின் கிரீடத்திற்குத் தேவையான விலைமதிப்பற்ற மாணிக்கக் கற்களை நவரத்தின வியாபாரியாக வந்து விற்ற லீலை."),
    ("வருணன் விட்ட கடலை வற்றச் செய்த படலம்", "சோழனின் சூழ்ச்சியால் வருணன் மதுரை மீது ஏவிய பிரளயக் கடலை நான்கு மேகங்களாக்கி வற்றச் செய்த நான்மாடக்கூடல் லீலை."),

    # 19-48: கூடற் காண்டம் (30 லீலைகள்)
    ("நான்மாடக் கூடலான படலம்", "வருணன் அனுப்பிய மழையிலிருந்து மதுரையைக் காக்க நான்கு மாடங்களாக நான்கு மேகங்களை நிலைநிறுத்திய லீலை."),
    ("எல்லாம் வல்ல சித்தரான படலம்", "மதுரை வீதிகளில் பித்தன் போல உலாவி, கல்லால் ஆன யானைக்குக் கரும்பு தின்னக் கொடுத்து அற்புதம் செய்த சித்தரின் லீலை."),
    ("கல்லானைக்குக் கரும்பு தந்த படலம்", "அரசனின் கர்வத்தை அடக்க, கோயில் வாசலில் நின்ற கல் யானைக்கு உயிரூட்டி முழுக் கரும்பைத் தின்ன வைத்த லீலை."),
    ("கரியக்குருவிக்கு உபதேசம் செய்த படலம்", "எளிய கரிய குருவி ஒன்றுக்கு மிருத்யுஞ்சய மந்திரத்தை உபதேசித்து சிவலோகப் பேறு அருளிய லீலை."),
    ("நாரைக்கு முக்தி அருளிய படலம்", "பொற்றாமரைக் குளத்தில் மீன் பிடிக்காமல் சிவனை வழிபட்ட நாரைக்கு நற்கதி அருளி, குளத்தில் மீன்கள் பிறக்காதிருக்க வரம் தந்த லீலை."),
    ("திருவாலவாயான படலம்", "மதுரையின் எல்லையை வரையறுக்க ஆதிசேஷனைத் தன் வாலால் வட்டம் போடச் செய்து திருவாலவாய் எனப் பெயர் தந்த லீலை."),
    ("பாண்டியன் சேனைக்கு உணவு அளித்த படலம்", "பஞ்சம் வந்த காலத்தில் பாண்டிய மன்னனின் பெரும் படைவீரர்களுக்கு அள்ள அள்ளக் குறையாத அமுதசுரபியாக உணவு அளித்த லீலை."),
    ("பொற்காசு அளித்த படலம்", "பஞ்சத்தில் வாடிய அடியார்களுக்கு நாடோறும் பொற்காசுகள் வழங்கித் துயர் துடைத்த லீலை."),
    ("மாமியாருக்குப் பிதிர் கடன் முடித்த படலம்", "தன் பக்தையான மூதாட்டிக்கு அவளது மாமியார் உருவத்தில் வந்து பிதுர் கடன்களை முடித்துக் கொடுத்த லீலை."),
    ("வருணன் செருக்கடக்கிய படலம்", "வருண பகவானின் மமதையை அடக்கி மதுரையை நித்திய மங்கள நகரமாக வாழ வைத்த லீலை."),
    ("விரகு விற்ற படலம்", "பாணபத்திரரின் இசைக் கர்வத்தை அடக்க வந்த ஹேமநாதனை ஓடச் செய்ய விறகுவெட்டியாக வந்து பாடிய லீலை."),
    ("திருமுகம் கொடுத்த படலம்", "பாணபத்திரருக்குப் பொன் பொருள் பெறச் சேரமான் பெருமாள் நாயனாருக்கு 'மதிமலி புரிசை' திருமுகம் எழுதி அனுப்பிய லீலை."),
    ("பலகை இட்ட படலம்", "மழைக்காலத்தில் நனைந்து பாடிய பாணபத்திரர் குளிரில் நடுங்காமல் இருக்கப் பொற்பலகை இட்டு அமரச் செய்த லீலை."),
    ("உலவாக்கிழி அருளிய படலம்", "பாணபத்திரரின் வறுமையைப் போக்க அள்ள அள்ளக் குறையாத அட்சய பாத்திரமாக பொற்கிழியை அருளிய லீலை."),
    ("வளையல் விற்ற படலம்", "தாருகாவனத்து முனிவர்களின் மனைவியருக்கு வளையல் வியாபாரியாக வந்து அழகிய வளையல்களை அணிவித்து ஆட்கொண்ட லீலை."),
    ("அட்டமாசித்தி உபதேசித்த படலம்", "எட்டு வகை மாபெரும் சித்திகளையும் முனிவர்களுக்கு மதுரை ஆலவாயில் அமர்ந்து உபதேசித்த லீலை."),
    ("விடையிலச்சினை இட்ட படலம்", "சோழ மன்னனின் கருவூலத்துப் பொற்காசுகளில் ரிஷப முத்திரையைப் பதித்து உண்மையை உணர்த்திய லீலை."),
    ("சோழனை மடுவில் வீழ்த்திய படலம்", "மதுரை மீது படையெடுத்து வந்த சோழனை வைகை மடுவில் வீழ்த்தி தர்மத்தைக் காத்த லீலை."),
    ("உலவாக் கோட்டை அருளிய படலம்", "பாண்டியனின் தானியக் களஞ்சியம் என்றும் வற்றாமல் நிறைந்திருக்க உலவாக் கோட்டையை அருளிய லீலை."),
    ("மாமனாக வந்து வழக்குரைத்த படலம்", "தாயற்ற அநாதைக் குழந்தைக்குச் சொந்தமான சொத்துக்களை அபகரித்த உறவினர்களிடம் மாமனாக வந்து வழக்காடி மீட்ட லீலை."),
    ("வரகுணனுக்குச் சிவலோகம் காட்டிய படலம்", "பிரம்மஹத்தி தோஷத்தால் தவித்த வரகுண பாண்டியனுக்கு திருவிடைமருதூரில் சாபம் நீக்கி சிவலோக தரிசனம் காட்டிய லீலை."),
    ("சுந்தரப் பலகை அருளிய படலம்", "தமிழ்ச் சங்கப் புலவர்கள் அமர்ந்து தமிழ் வளர்க்கத் தலைசிறந்த ஞான பீடமாகச் சங்கப் பலகையை அருளிய லீலை."),
    ("தருமிக்குப் பொற்கிழி அளித்த படலம்", "ஏழை அந்தணன் தருமிக்குத் திருமண உதவி செய்ய 'கொங்குதேர் வாழ்க்கை' பாடலைத் தம் கைப்பட எழுதித் தந்த லீலை."),
    ("நக்கீரர் நெற்றிக்கண் திறந்த படலம்", "பாடலில் குற்றம் சொன்ன நக்கீரருக்குத் தம் நெற்றிக் கண்ணைக் காட்டி, தமிழை வாழ வைத்த உன்னத லீலை."),
    ("நக்கீரரைக் குளத்தினின்று எடுத்த படலம்", "நெற்றிக்கண் தீப்பொறி தாங்காமல் பொற்றாமரைக் குளத்தில் விழுந்த நக்கீரரை மீண்டும் உயிர்ப்பித்துத் தமிழ் பாடும் ஆற்றல் தந்த லீலை."),
    ("இடைக்காடரின் பிணக்குத் தீர்த்த படலம்", "புலவர் இடைக்காடரை அவமதித்த பாண்டியனை விட்டு நீங்கி வடதிருவாலவாயில் சென்று தங்கி, அரசன் மனம் வருந்தி மன்னிப்புக் கேட்க மீண்ட லீலை."),
    ("வலைவீசி மீன் பிடித்த படலம்", "சாபத்தால் திமிங்கிலமாக மாறிய நந்திகேசரை மீட்கவும், மீனவப் பெண்ணாகப் பிறந்த உமையைத் திருமணம் செய்யவும் வலைஞனாக வந்து மீன் பிடித்த லீலை."),
    ("வாதவூரடிகளுக்கு உபதேசித்த படலம்", "திருப்பெருந்துறை குருந்த மரத்தடியில் மாணிக்கவாசகருக்கு ஞானாசிரியராகத் தோன்றி சிவஞான போதம் புகட்டிய லீலை."),
    ("நரியைப் பரியாக்கிய படலம்", "மாணிக்கவாசகரைக் காப்பாற்ற கானகத்து நரிகளை எல்லாம் மின்னும் அரேபியக் குதிரைகளாக்கி மதுரைக்கு ஓட்டி வந்த லீலை."),
    ("பரியை நரியாக்கிய படலம்", "இரவில் குதிரைகள் மீண்டும் நரிகளாக ஊளையிட்டு ஓடி, அரசனுக்கு உலக மாயையை உணர்த்திய லீலை."),

    # 49-64: திருவாலவாய்க் காண்டம் (16 லீலைகள்)
    ("மண் சுமந்து பிரம்படி பட்ட படலம்", "வைகை வெள்ளத்தை அடைக்க வந்தி பாட்டிக்குக் கூலியாகப் பிட்டு தின்று முதுகில் பிரம்படி பட்டு உலக உயிர்கள் அனைத்தையும் சிலிர்க்க வைத்த லீலை."),
    ("பாண்டியன் சுரம் தீர்த்த படலம்", "திருஞானசம்பந்தர் 'மந்திரமாவது நீறு' என்று திருநீறிட்டு பாண்டிய மன்னனின் கொடிய வெப்பு நோயைத் தீர்த்த லீலை."),
    ("சமணரை வாதில் வென்ற படலம்", "அனல் வாதம், புனல் வாதம் ஆகியவற்றில் திருமுறை ஏடுகள் எரியாமலும் நீரில் எதிர்நீந்திச் சென்றும் வென்ற லீலை."),
    ("பாண்டியன் கூன் நிமிர்த்திய படலம்", "கூன் பாண்டியனின் கூன் நிமிர்ந்து அவன் சுந்தர பாண்டியனாக சிவநெறியைத் தழுவிய லீலை."),
    ("பன்றிக்குட்டிகளுக்குப் பாலூட்டிய படலம்", "தாயை இழந்த பன்னிரண்டு அநாதைப் பன்றிக்குட்டிகளுக்குத் தாய்ப்பன்றியாக வந்து பாலூட்டி அமைச்சர்களாக்கிய எல்லையற்ற கருணை லீலை."),
    ("பன்றிக் குட்டிகளை அமைச்சராக்கிய படலம்", "மனித ஞானம் பெற்ற பன்றிக்குட்டிகள் பாண்டிய மன்னனின் அரசவையில் தர்ம நெறி தவறாத அமைச்சர்களாக நாடாண்ட லீலை."),
    ("குருவிக்கு உபதேசம் செய்த படலம்", "சிறிய கரிக்குருவியின் சிவபக்தியை மெச்சி அதற்கு அஷ்டமாசித்துக்களையும் சிவலோகப் பதவியையும் அருளிய லீலை."),
    ("மண்சுமந்த படலம் — தொடர்ச்சி", "உலக உயிர்கள் அனைத்துக்கும் அன்னமிடும் ஈசன், எளிய மூதாட்டியின் பிட்டுக்காக மண் சுமந்த தியாக லீலை."),
    ("சேரமான் பெருமாளுக்குத் திருமுகம் விடுத்த லீலை", "பாணபத்திரரின் இசையைப் போற்றிச் சேர மன்னனிடம் நிதி பெற்றுத் தந்த அருட்பாடல் லீலை."),
    ("தண்ணீர்ப் பந்தல் வைத்த லீலை", "வெயிலில் களைத்து வந்த அடியார்களின் தாகத்தைத் தீர்க்கத் தண்ணீர்ப் பந்தல் அமைத்துத் தானே தண்ணீர் வார்த்த லீலை."),
    ("ரசவாதம் செய்த லீலை", "பொன்பொருளற்ற ஏழை அடியாருக்கு இரும்பைப் பொன்னாக்கும் ரசவாத வித்தையை உபதேசித்து நல்வாழ்வு அளித்த லீலை."),
    ("சோழனை வென்ற லீலை", "அநியாயமாகப் படையெடுத்து வந்த பகைவர்களைத் தன் பூத சேனைகளைக் கொண்டு விரட்டியடித்த லீலை."),
    ("செல்லூர் மாயை தீர்த்த லீலை", "மக்களுக்கு ஏற்பட்ட தீராத மாய நோய்களைத் தீர்த்து வைத்த தெய்வீக லீலை."),
    ("சாபம் தீர்த்த லீலை", "சாபங்களால் பிறவிகள் தோறும் தவித்த எளிய விலங்குகளுக்கும் பறவைகளுக்கும் சாபவிமோசனம் அளித்த லீலை."),
    ("சிவலோகம் அருளிய லீலை", "மதுரையில் வாழ்ந்து முக்கண்ணனை வழிபட்ட சாமானிய மக்களுக்கும் வைகுந்த-கைலாயப் பேரின்ப முக்தியை வழங்கிய லீலை."),
    ("முழு லீலைகளின் நிறைவு & மதுரை மான்மியம்", "64 திருவிளையாடல்களையும் கேட்டோர்க்கும் படித்தோர்க்கும் சகல நன்மைகளும் தீர்க்காயுளும் அமைதியும் உண்டாகும் என்ற மங்கள நிறைவு.")
]

